'use strict';
let homeSong=songs[0],homeMode='learn';
const homePicker=document.createElement('dialog');homePicker.id='home-picker';homePicker.innerHTML=`<div class="picker-top"><div><span class="welcome-tag">♫ 一首一首，慢慢喜欢</span><h2>今天，想弹哪一首？</h2><p>12 首入门到进阶的简化旋律片段。</p></div><button id="home-picker-close" aria-label="关闭选曲">×</button></div><div class="home-picker-filters"><input id="home-song-search" type="search" placeholder="搜索曲名或作者…" aria-label="搜索曲名或作者"><select id="home-song-level" aria-label="选择难度"><option>全部难度</option><option>入门</option><option>初级</option><option>进阶</option></select></div><div id="home-song-list"></div>`;document.body.append(homePicker);
const coverFor=id=>['★','♫','☁','♬'][id%4];
function selectHomeSong(id){homeSong=songs.find(s=>s.id===id)||songs[0];$('#home-song-title').replaceChildren(document.createTextNode(homeSong.name+' '));const badge=document.createElement('span');badge.className='difficulty-badge';badge.textContent=homeSong.level;$('#home-song-title').append(badge);$('#home-cover').textContent=coverFor(homeSong.id);$$('#featured .song').forEach(b=>b.classList.toggle('home-selected',+b.dataset.song===id));$('#home-start').classList.remove('action-nudge');void $('#home-start').offsetWidth;$('#home-start').classList.add('action-nudge');}
function renderHomePicker(){const q=$('#home-song-search').value.trim().toLowerCase(),level=$('#home-song-level').value;const filtered=songs.filter(s=>(s.name+s.author).toLowerCase().includes(q)&&(level==='全部难度'||s.level===level));$('#home-song-list').innerHTML=filtered.length?filtered.map(s=>`<button data-home-song="${s.id}" class="home-picker-song ${s.id===homeSong.id?'chosen':''}"><span class="selected-cover">${coverFor(s.id)}</span><span><b>${s.name}</b><small>${s.author}</small></span><em>${s.level}</em><span>${s.id===homeSong.id?'✓ 已选':'选择 →'}</span></button>`).join(''):'<p class="empty-message">没有找到这首歌，换个关键词试试。</p>';}
function openHomePicker(){allOff();renderHomePicker();homePicker.showModal();$('#home-song-search').focus()}
$('#home-choose-song').onclick=$('#home-open-search').onclick=openHomePicker;$('#home-picker-close').onclick=()=>homePicker.close();$('#home-song-search').oninput=$('#home-song-level').onchange=renderHomePicker;$('#home-song-list').onclick=e=>{const b=e.target.closest('[data-home-song]');if(!b)return;selectHomeSong(+b.dataset.homeSong);homePicker.close();$('#home-start').focus()};
$$('[data-home-mode]').forEach(b=>b.onclick=()=>{homeMode=b.dataset.homeMode;$$('[data-home-mode]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#home-start').innerHTML={auto:'开始播放 <span>→</span>',free:'进入演奏 <span>→</span>',learn:'开始练习 <span>→</span>'}[homeMode];$('#home-mode-description').textContent={auto:'先听一遍，感受旋律怎样起伏。',free:'没有对错，试着弹出自己的声音。',learn:'跟着高亮琴键，慢慢弹会这首歌。'}[homeMode]});
$('#home-start').onclick=()=>{if(homeMode==='free'){page('free');$('.piano-panel').scrollIntoView({behavior:'smooth',block:'center'});return}start(homeSong,'s'+homeSong.id);if(homeMode==='auto'){chapter('listen');$('#room-demo').click()}else{chapter('play');$('#room-play').click()}};
document.addEventListener('click',e=>{const b=e.target.closest('#featured [data-song]');if(!b)return;e.stopImmediatePropagation();selectHomeSong(+b.dataset.song);},true);
// Keep navigation labels human-readable without changing the existing page controller.
const gardenPage=page;page=function(id){gardenPage(id);$('#page-name').textContent={learn:'首页',library:'曲库',practice:'专项训练',free:'自由弹奏'}[id]||'首页'};
const gardenStart=start;start=function(item,key){if(homePicker.open)homePicker.close();gardenStart(item,key)};
const gardenPress=press;press=function(m,source){if(homePicker.open)return;gardenPress(m,source);const key=els[m];if(key&&!String(source).startsWith('demo')&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){const spark=document.createElement('span');spark.className='key-spark';spark.textContent=['♪','♫','✦'][m%3];key.append(spark);setTimeout(()=>spark.remove(),650)}};
if(['#library','#practice','#free'].includes(location.hash))page(location.hash.slice(1));selectHomeSong(0);
$('nav [data-page="learn"]').textContent='⌂　首页';$('#page-name').textContent=$('#learn').classList.contains('active')?'首页':$('#page-name').textContent;
$('.brand small').textContent='把喜欢，弹成音乐';$('.live-entry').innerHTML='<span>✦ 我的舞台</span><small>高手空间 ↗</small>';
